import type { Entry } from '../src/lib/entry.js'

export const MAX_PICKS = 8
export const MAX_QUERY_LENGTH = 400
export const MAX_REASON_LENGTH = 200
export const DAILY_LIMIT = 60

export interface Pick {
  slug: string
  reason: string
}

const orUnknown = (value: string | null | undefined): string => value?.trim() || 'unknown'

export function buildCatalog(entries: Entry[]): string {
  return entries
    .map((e) => {
      const offers = e.offers.map((o) => `${o.meal} $${o.price}`).join(', ')
      const moods = e.moods.map((m) => m.tag).join(', ')
      return [
        e.slug,
        orUnknown(e.name),
        orUnknown(e.neighborhood),
        orUnknown(e.cuisine),
        orUnknown(offers),
        e.menuCoverage === 'none' ? 'no menu published' : moods || 'no mood tags',
        orUnknown(e.blurb),
      ].join(' | ')
    })
    .join('\n')
}

export function validateShortlist(raw: unknown, knownIds: Set<string>): Pick[] {
  if (typeof raw !== 'object' || raw === null) return []
  const picks = (raw as Record<string, unknown>).picks
  if (!Array.isArray(picks)) return []

  const seen = new Set<string>()
  const out: Pick[] = []

  for (const p of picks) {
    if (typeof p !== 'object' || p === null) continue
    const { slug, reason } = p as Record<string, unknown>
    if (typeof slug !== 'string' || typeof reason !== 'string') continue
    if (!knownIds.has(slug) || seen.has(slug)) continue
    seen.add(slug)
    out.push({ slug, reason: reason.slice(0, MAX_REASON_LENGTH) })
    if (out.length === MAX_PICKS) break
  }
  return out
}

export const SHORTLIST_SYSTEM_PROMPT = `You pick restaurants for San Francisco Restaurant Week, 16 to 25 October 2026.

You receive a catalog, one restaurant per line, in this shape:
slug | name | neighborhood | cuisine | offers | mood tags | blurb

Return only JSON: { "picks": [{ "slug": string, "reason": string }] }

Rules:
- Use at most ${MAX_PICKS} picks. Fewer is better when fewer genuinely fit.
- "slug" must be copied exactly from the catalog. Never invent one.
- "reason" is one sentence, under 15 words, naming the concrete thing that
  matches the request. Do not restate the request.
- When nothing fits well, return fewer picks rather than padding the list.`

export const MAX_RESPONSE_TOKENS = 4000

// Sent as output_config.format. Without it the model may wrap its answer in a
// code fence or prose, and a truncated response parses as nothing at all.
export const SHORTLIST_SCHEMA = {
  type: 'object',
  properties: {
    picks: {
      type: 'array',
      maxItems: MAX_PICKS,
      items: {
        type: 'object',
        properties: { slug: { type: 'string' }, reason: { type: 'string' } },
        required: ['slug', 'reason'],
        additionalProperties: false,
      },
    },
  },
  required: ['picks'],
  additionalProperties: false,
} as const

export function validateQuery(query: unknown): 'bad_request' | 'query_too_long' | null {
  if (typeof query !== 'string' || !query.trim()) return 'bad_request'

  }

  const invalid = validateQuery(query)
  if (invalid) return json({ error: invalid }, 400)

  if (!env.ANTHROPIC_API_KEY) {
    console.error('ANTHROPIC_API_KEY is not configured; skipping rate limit and upstream call')
    return json({ error: 'upstream_failed' }, 502)
  }

  const ip = request.headers.get('CF-Connecting-IP') ?? 'unknown'
  try {
    if (await overDailyLimit(env.KV, ip)) return json({ error: 'rate_limited' }, 429)
  } catch (err) {
    console.error('rate limit store failed', err instanceof Error ? err.name : 'unknown')
    return json({ error: 'unavailable' }, 503)
  }

  try {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: anthropicHeaders(env.ANTHROPIC_API_KEY, env.ANTHROPIC_WORKSPACE_ID),
      body: JSON.stringify({
        model: 'claude-sonnet-5-5',
        max_tokens: MAX_RESPONSE_TOKENS,
        system: [
          { type: 'text', text: SHORTLIST_SYSTEM_PROMPT },
          { type: 'text', text: CATALOG, cache_control: { type: 'ephemeral' } },
        ],
        messages: [{ role: 'user', content: query as string }],
        // Thinking is on by default on this model and its tokens count against
        // max_tokens, which starved the answer. This model rejects `disabled`.
        thinking: { type: 'between_tools' },
        output_config: { format: { type: 'json_schema', schema: SHORTLIST_SCHEMA } },
      }),
    })
    if (!res.ok) {
      console.error('upstream returned status', res.status)
      return json({ error: 'upstream_failed' }, 502)
    }

    const body = (await res.json()) as {
      stop_reason: string
      content: Array<{ type: string; text?: string }>
    }
    if (body.stop_reason === 'max_tokens') {
      console.error('upstream response hit max_tokens')
      return json({ error: 'upstream_failed' }, 502)
    }

    const text = body.content.find((c) => c.type === 'text')?.text ?? ''
    // Structured output returns bare JSON, so this only matters if the model
    // ever wraps it in prose. Safe now that max_tokens is rejected above: a
    // truncated body can no longer slice down to a valid-looking partial object.
    const parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1))
    return json({ picks: validateShortlist(parsed, KNOWN) })
  } catch (err) {
    console.error('upstream call failed', err instanceof Error ? err.name : 'unknown')
    return json({ error: 'upstream_failed' }, 502)
  }
}

